# ═══════════════════════════════════════════════════════════════════════════
# Substitution rules: legal instruction swaps across pipes
#
# These describe HOW to move work between pipes, including the true cost.
# The rebalancer (not yet built) would use these; the analyzer just reports
# what's possible.
#
# Key constraint: BF16 ops are PACKED (2 values per instruction).
# Moving 1 HFMA2 to ALU requires 2 FFMA (scalar FP32), plus conversion
# costs if the data isn't already in FP32.
# ═══════════════════════════════════════════════════════════════════════════

SUBSTITUTIONS = [
    {
        'name': 'HADD2 → 2×FFMA',
        'from_family': 'HADD2',
        'from_pipe': 'BF16',
        'to_family': 'FFMA',
        'to_pipe': 'ALU',
        'expansion': 2,
        #   BF16 packed pair → must unpack to 2 FP32 scalars before FFMA,
        #   then repack 2 FP32 results → BF16 pair afterward.
        #   Unpacking: 2× PRMT (ALU, 2 cyc each) or 2× SHF
        #   Repacking: 1× F2FP (BF16 pipe, 2 cyc) — converts 2 FP32 → 1 BF16x2
        #   Net: saves 1 BF16-pipe slot (HADD2), costs 2 ALU slots (FFMA) +
        #         2 ALU slots (unpack) + 1 BF16 slot (repack F2FP).
        #   IF DATA IS ALREADY FP32 (e.g., right after F2FP output before packing):
        #     saves 1 BF16 slot (HADD2), costs 2 ALU slots (FFMA). No conversion.
        #     But you lose the F2FP that would have packed — net: -1 BF16, +2 ALU.
        'extra_ops_bf16_to_bf16': {
            'ALU': 2,     # 2× PRMT/SHF for unpack (if input is BF16)
            'BF16': 1,    # 1× F2FP for repack (if output must be BF16)
        },
        'extra_ops_fp32_context': {
            'ALU': 0,     # no unpack needed — data already FP32
            'BF16': 0,    # no repack needed — stays in FP32 until final STS
        },
        'notes': (
            'Best when both inputs are already FP32 (e.g., post-F2FP conversion). '
            'If inputs are BF16 pairs, unpack cost (2×ALU + 1×BF16 repack) makes '
            'the swap expensive: net saves 0 BF16 slots and adds 4 ALU slots. '
            'Only profitable when BF16 pipe is >2× overloaded vs ALU.'
        ),
    },
    {
        'name': 'HFMA2 → 2×FFMA',
        'from_family': 'HFMA2',
        'from_pipe': 'BF16',
        'to_family': 'FFMA',
        'to_pipe': 'ALU',
        'expansion': 2,
        'extra_ops_bf16_to_bf16': {
            'ALU': 2,     # unpack BF16 → 2 FP32
            'BF16': 1,    # repack 2 FP32 → BF16x2
        },
        'extra_ops_fp32_context': {
            'ALU': 0,
            'BF16': 0,
        },
        'notes': (
            'Same as HADD2→FFMA. HFMA2.BF16_V2 Rd,Ra,1,1,Rb is multiply-by-1-add, '
            'equivalent to FFMA Rd,Ra,1.0,Rb in FP32. The "×1" disappears in FFMA.'
        ),
    },
    {
        'name': 'F2FP: BF16 pipe, no ALU alternative',
        'from_family': 'F2FP',
        'from_pipe': 'BF16',
        'to_family': None,
        'to_pipe': None,
        'expansion': 0,
        'notes': (
            'F2FP.BF16.F32.PACK_AB converts 2×FP32 → 1×BF16x2. There is no ALU '
            'equivalent — this is a format conversion, not arithmetic. F2FP is '
            'ALWAYS on the BF16 pipe. Any template that outputs BF16 must pay this '
            'cost. The only way to reduce F2FP count is to defer conversion: do all '
            'arithmetic in FP32 and convert only at the final STS boundary.'
        ),
    },
    {
        'name': 'FFMA → HFMA2 (pack 2 scalar FP32 → 1 packed BF16)',
        'from_family': 'FFMA',
        'from_pipe': 'ALU',
        'to_family': 'HFMA2',
        'to_pipe': 'BF16',
        'expansion': 0.5,
        'extra_ops_bf16_to_bf16': {
            'BF16': 0,   # no conversion if both inputs already BF16
            'ALU': 0,
        },
        'extra_ops_fp32_context': {
            'BF16': 2,   # 2× F2FP to convert 4 FP32 inputs → 2 BF16x2
            'ALU': 0,
        },
        'notes': (
            'Only possible when two independent scalar FP32 adds can be paired '
            'into one packed BF16 op. Requires inputs to be in BF16 format or '
            'paying 2× F2FP conversion cost. Precision loss: BF16 has 8-bit '
            'mantissa vs FP32 23-bit. Usually only useful for CUTLASS→our format.'
        ),
    },
]


# ═══════════════════════════════════════════════════════════════════════════
# Pipe analyzer — diagnose utilization imbalance in instruction sequences
# ═══════════════════════════════════════════════════════════════════════════

def classify_instruction(mnemonic):
    """Classify instruction mnemonic → pipe name.

    Strips predicate guards and suffix modifiers to find the base family.
    Returns (pipe, base_family) or ('UNKNOWN', mnemonic) if not found.
    """
    mn = mnemonic
    # Strip predicate guard
    if mn.startswith('@'):
        parts = mn.split(None, 1)
        mn = parts[1] if len(parts) > 1 else mn

    # Try exact match first (handles dotted names like STS.128)
    if mn in PIPE_CLASS:
        return PIPE_CLASS[mn], mn

    # Try base family (before first dot)
    base = mn.split('.')[0]
    if base in PIPE_CLASS:
        return PIPE_CLASS[base], base

    return 'UNKNOWN', mn


def analyze_pipes(instructions, title='Template', verbose=True):
    """Analyze pipe utilization of an instruction sequence.

    instructions: list of (mnemonic, count) tuples, or list of mnemonic strings.
    Returns a dict with analysis results.

    Prints a detailed diagnostic if verbose=True.
    """
    # Normalize input
    if instructions and isinstance(instructions[0], str):
        # Count occurrences
        from collections import Counter
        raw_counts = Counter()
        for mn in instructions:
            mn = mn.strip()
            if not mn or mn.startswith('#') or mn.startswith('.'):
                continue
            if mn.startswith('@'):
                parts = mn.split(None, 1)
                mn = parts[1] if len(parts) > 1 else mn
            base = mn.split()[0]
            raw_counts[base] += 1
        instructions = list(raw_counts.items())

    # Classify each instruction
    pipe_ops = {}      # pipe → total op count
    pipe_detail = {}   # pipe → {family: count}
    bf16_slow_count = 0
    total_insns = 0
    unknowns = []

    for mnemonic, count in instructions:
        pipe, family = classify_instruction(mnemonic)
        total_insns += count

        if pipe == 'UNKNOWN':
            unknowns.append((mnemonic, count))
            continue

        pipe_ops[pipe] = pipe_ops.get(pipe, 0) + count
        if pipe not in pipe_detail:
            pipe_detail[pipe] = {}
        pipe_detail[pipe][family] = pipe_detail[pipe].get(family, 0) + count

        if family in BF16_SLOW_FAMILIES:
            bf16_slow_count += count

    # Compute cycles per pipe
    pipe_cycles = {}
    for pipe, count in pipe_ops.items():
        tput = PIPE_THROUGHPUT.get(pipe, 0)
        pipe_cycles[pipe] = count * tput

    # BF16 effective throughput adjustment
    bf16_total = pipe_ops.get('BF16', 0)
    bf16_cycles_adjusted = 0
    if bf16_total > 0:
        bf16_fast = bf16_total - bf16_slow_count  # F2FP etc.
        bf16_cycles_adjusted = bf16_fast * 2 + bf16_slow_count * 3
        # Use the worse estimate (conservative)
        pipe_cycles['BF16'] = max(pipe_cycles.get('BF16', 0), bf16_cycles_adjusted)

    # Find bottleneck among compute pipes (ALU, BF16) and memory pipes separately
    # MEM (STS/LDS) is scheduling-dependent: STS throughput = 32 cyc back-to-back,
    # but each STS can shadow up to ~4 BF16/ALU ops (effectively free work).
    # In an interleaved schedule, MEM rarely dominates. Report it separately.
    compute_only = {p: c for p, c in pipe_cycles.items() if p in ('ALU', 'BF16')}
    all_nonzero = {p: c for p, c in pipe_cycles.items() if c > 0}

    if compute_only:
        compute_bottleneck = max(compute_only, key=compute_only.get)
        compute_bottleneck_cyc = compute_only[compute_bottleneck]
    else:
        compute_bottleneck = None
        compute_bottleneck_cyc = 0

    if all_nonzero:
        bottleneck_pipe = max(all_nonzero, key=all_nonzero.get)
        bottleneck_cycles = all_nonzero[bottleneck_pipe]
    else:
        bottleneck_pipe = None
        bottleneck_cycles = 0

    # Substitution analysis (based on compute bottleneck, not MEM)
    sub_analysis = []
    if compute_bottleneck in ('BF16', 'ALU'):
        target_pipe = 'ALU' if compute_bottleneck == 'BF16' else 'BF16'
        for sub in SUBSTITUTIONS:
            if sub['from_pipe'] != compute_bottleneck:
                continue
            if sub['to_pipe'] is None:
                sub_analysis.append({
                    'rule': sub['name'],
                    'movable_count': pipe_detail.get(compute_bottleneck, {}).get(sub['from_family'], 0),
                    'expansion': sub['expansion'],
                    'notes': sub['notes'],
                    'blocked': True,
                })
                continue
            movable = pipe_detail.get(compute_bottleneck, {}).get(sub['from_family'], 0)
            if movable == 0:
                continue
            sub_analysis.append({
                'rule': sub['name'],
                'movable_count': movable,
                'expansion': sub['expansion'],
                'target_pipe': target_pipe,
                'extra_ops': sub.get('extra_ops_fp32_context', {}),
                'notes': sub['notes'],
                'blocked': False,
            })

    # Balance computation (what if we moved N ops?)
    balance_info = None
    if compute_bottleneck == 'BF16' and 'ALU' in pipe_cycles:
        alu_cyc = pipe_cycles['ALU']
        bf16_cyc = pipe_cycles['BF16']
        # Movable: HADD2 + HFMA2 (not F2FP — locked to BF16)
        movable_bf16 = sum(
            pipe_detail.get('BF16', {}).get(f, 0)
            for f in ('HADD2', 'HFMA2', 'HMUL2')
        )
        if movable_bf16 > 0:
            # Each moved op: -1 BF16 slot (saves tput cyc), +2 ALU slots (expansion)
            # In FP32 context (no unpack/repack): -2 BF16 cyc, +4 ALU cyc
            # With BF16 pack/unpack: -2 BF16 cyc + 2 repack, +4 ALU + 4 unpack
            # Best case: FP32 context
            # BF16 effective tput for HADD2/HFMA2 = 3 cyc
            # Solve: (bf16_cyc - 3*N) = (alu_cyc + 2*2*N) for balance
            #   bf16_cyc - 3N = alu_cyc + 4N  →  N = (bf16_cyc - alu_cyc) / 7
            # But this assumes FP32 context. With BF16 context add repack cost.
            N_fp32 = (bf16_cyc - alu_cyc) / 7.0
            N_fp32 = max(0, min(movable_bf16, int(N_fp32)))
            new_bf16 = bf16_cyc - N_fp32 * 3
            new_alu = alu_cyc + N_fp32 * 2 * 2
            balance_info = {
                'movable_ops': movable_bf16,
                'optimal_N_fp32_context': N_fp32,
                'current_bf16_cyc': bf16_cyc,
                'current_alu_cyc': alu_cyc,
                'balanced_bf16_cyc': new_bf16,
                'balanced_alu_cyc': new_alu,
                'savings_pct': (1 - max(new_bf16, new_alu) / bf16_cyc) * 100,
            }

    elif compute_bottleneck == 'ALU' and 'BF16' in pipe_cycles:
        alu_cyc = pipe_cycles['ALU']
        bf16_cyc = pipe_cycles['BF16']
        movable_alu = sum(
            pipe_detail.get('ALU', {}).get(f, 0)
            for f in ('FFMA', 'FADD', 'FMUL')
        )
        if movable_alu > 0:
            # 2 FFMA → 1 HFMA2: saves 2 ALU slots, costs 1 BF16 slot
            # But need pairs. And may need F2FP conversion.
            N_alu = (alu_cyc - bf16_cyc) / 6.0  # 2*2 saved ALU + 1*2 added BF16
            N_alu = max(0, min(movable_alu // 2, int(N_alu)))
            new_alu = alu_cyc - N_alu * 2 * 2
            new_bf16 = bf16_cyc + N_alu * 2
            balance_info = {
                'movable_ops': movable_alu,
                'optimal_N_pairs': N_alu,
                'current_alu_cyc': alu_cyc,
                'current_bf16_cyc': bf16_cyc,
                'balanced_alu_cyc': new_alu,
                'balanced_bf16_cyc': new_bf16,
                'savings_pct': (1 - max(new_bf16, new_alu) / alu_cyc) * 100,
            }

    result = {
        'total_insns': total_insns,
        'pipe_ops': pipe_ops,
        'pipe_detail': pipe_detail,
        'pipe_cycles': pipe_cycles,
        'bottleneck_pipe': bottleneck_pipe,
        'bottleneck_cycles': bottleneck_cycles,
        'compute_bottleneck': compute_bottleneck,
        'compute_bottleneck_cyc': compute_bottleneck_cyc,
        'bf16_slow_count': bf16_slow_count,
        'substitutions': sub_analysis,
        'balance': balance_info,
        'unknowns': unknowns,
    }

    if verbose:
        _print_analysis(result, title)

    return result


def _print_analysis(r, title):
    """Print formatted pipe analysis diagnostic."""
    print(f'\n{"=" * 70}')
    print(f'  PIPE UTILIZATION ANALYSIS: {title}')
    print(f'  {r["total_insns"]} instructions total')
    print(f'{"=" * 70}')

    # Pipe breakdown
    max_cyc = max(r['pipe_cycles'].values()) if r['pipe_cycles'] else 1
    pipe_order = ['BF16', 'ALU', 'MEM', 'GMEM', 'TMA', 'TMEM',
                  'BARRIER', 'CONTROL', 'FAST_INT', 'SPECIAL']

    # Use compute bottleneck for bar scaling (MEM is scheduling-dependent)
    compute_max = max(
        (r['pipe_cycles'].get(p, 0) for p in ('BF16', 'ALU', 'MEM')),
        default=1
    )
    if compute_max == 0:
        compute_max = max_cyc if max_cyc > 0 else 1

    print(f'\n  {"Pipe":<12} {"Ops":>5} {"Cyc":>6} {"Tput":>5}  Utilization')
    print(f'  {"─" * 55}')

    for pipe in pipe_order:
        if pipe not in r['pipe_ops']:
            continue
        ops = r['pipe_ops'][pipe]
        cyc = r['pipe_cycles'].get(pipe, 0)
        tput = PIPE_THROUGHPUT.get(pipe, 0)
        bar_len = int(30 * cyc / compute_max) if compute_max > 0 else 0
        bar = '█' * bar_len
        if pipe == r['compute_bottleneck']:
            marker = ' ◄ COMPUTE BOTTLENECK'
        elif pipe == r['bottleneck_pipe'] and pipe != r['compute_bottleneck']:
            marker = ' (scheduling-dependent)'
        else:
            marker = ''
        tput_str = f'{tput}c' if tput > 0 else 'free'
        print(f'  {pipe:<12} {ops:>5} {cyc:>6} {tput_str:>5}  {bar}{marker}')

    # MEM caveat
    mem_ops = r['pipe_ops'].get('MEM', 0)
    if mem_ops > 0:
        sts_count = r['pipe_detail'].get('MEM', {}).get('STS', 0) + \
                    r['pipe_detail'].get('MEM', {}).get('STS.128', 0)
        if sts_count > 0:
            print(f'\n  ℹ  MEM cycle count assumes back-to-back STS ({sts_count}× STS.128 '
                  f'× 32 cyc = {sts_count * 32} cyc).')
            print(f'     In practice, each STS shadows ~4 free compute ops. With good')
            print(f'     scheduling (interleaved STS), effective MEM cost is much lower.')
            print(f'     Compute pipe balance matters more than raw MEM throughput.')

    # Detail breakdown for compute pipes
    for pipe in ('BF16', 'ALU', 'MEM'):
        if pipe in r['pipe_detail'] and len(r['pipe_detail'][pipe]) > 1:
            print(f'\n  {pipe} detail:')
            for fam, cnt in sorted(r['pipe_detail'][pipe].items(),
                                   key=lambda x: -x[1]):
                slow = ' (3 cyc @ ILP=2)' if fam in BF16_SLOW_FAMILIES else ''
                print(f'    {fam:<20} {cnt:>4}{slow}')

    # BF16 throughput warning
    if r['bf16_slow_count'] > 0:
        bf16_total = r['pipe_ops'].get('BF16', 0)
        pct = r['bf16_slow_count'] / bf16_total * 100 if bf16_total else 0
        print(f'\n  ⚠  BF16 throughput warning: {r["bf16_slow_count"]}/{bf16_total} '
              f'ops ({pct:.0f}%) are HADD2/HFMA2 (3 cyc @ ILP=2, not 2 cyc).')
        print(f'     Effective BF16 critical path ≈ {r["pipe_cycles"].get("BF16", 0)} cyc '
              f'(not {bf16_total * 2} cyc).')

    # Unknowns
    if r['unknowns']:
        print(f'\n  ⚠  Unclassified instructions:')
        for mn, cnt in r['unknowns']:
            print(f'    {mn:<20} {cnt:>4}')

    # Substitution analysis
    if r['substitutions']:
        print(f'\n  SUBSTITUTION OPPORTUNITIES')
        print(f'  {"─" * 55}')
        for sub in r['substitutions']:
            if sub['blocked']:
                print(f'  ✗ {sub["rule"]}: {sub["movable_count"]} ops — NOT SUBSTITUTABLE')
                print(f'    {sub["notes"][:100]}')
            else:
                exp = sub['expansion']
                n = sub['movable_count']
                print(f'  → {sub["rule"]}: {n} ops available (1:{exp} expansion)')
                if sub.get('extra_ops'):
                    extras = ', '.join(f'+{v} {k}' for k, v in sub['extra_ops'].items() if v)
                    if extras:
                        print(f'    Conversion overhead per swap: {extras}')
                # Truncate notes sensibly
                notes = sub['notes']
                if len(notes) > 120:
                    notes = notes[:117] + '...'
                print(f'    {notes}')

    # Balance recommendation
    bal = r['balance']
    if bal:
        print(f'\n  BALANCE RECOMMENDATION')
        print(f'  {"─" * 55}')
        if 'optimal_N_fp32_context' in bal:
            N = bal['optimal_N_fp32_context']
            print(f'  Move {N} of {bal["movable_ops"]} substitutable ops from '
                  f'BF16 → ALU:')
            print(f'    BF16: {bal["current_bf16_cyc"]:>4} cyc → {bal["balanced_bf16_cyc"]:>4} cyc')
            print(f'    ALU:  {bal["current_alu_cyc"]:>4} cyc → {bal["balanced_alu_cyc"]:>4} cyc')
            print(f'    Critical path reduction: {bal["savings_pct"]:.1f}%')
            print()
            print(f'  ⚠  CONVERSION COSTS — these estimates assume FP32 context:')
            print(f'     Best case: data is already FP32 (e.g., bias+residual applied')
            print(f'     AFTER F2FP but BEFORE final packing). Only 2×FFMA per op.')
            print(f'     Worst case: data in BF16 pairs. Each swap costs +2 ALU (unpack)')
            print(f'     + 1 BF16 (F2FP repack), nearly eliminating the savings.')
            print(f'     The key: restructure the computation order so bias+residual')
            print(f'     addition happens in FP32 BEFORE the BF16 conversion step.')
        elif 'optimal_N_pairs' in bal:
            N = bal['optimal_N_pairs']
            print(f'  Move {N} FFMA pairs from ALU → BF16 (as {N} HFMA2):')
            print(f'    ALU:  {bal["current_alu_cyc"]:>4} cyc → {bal["balanced_alu_cyc"]:>4} cyc')
            print(f'    BF16: {bal["current_bf16_cyc"]:>4} cyc → {bal["balanced_bf16_cyc"]:>4} cyc')
            print(f'    Critical path reduction: {bal["savings_pct"]:.1f}%')
            print()
            print(f'  ⚠  Requires pairable scalar FP32 ops (independent lo/hi halves)')
            print(f'     and BF16 precision is acceptable (8-bit vs 23-bit mantissa).')

    if not r['substitutions'] and not bal:
        cb = r['compute_bottleneck']
        if cb is None or r['compute_bottleneck_cyc'] == 0:
            print(f'\n  No significant compute work. Bottleneck is '
                  f'{r["bottleneck_pipe"] or "none"}.')
        else:
            ratio = 0
            other = 'ALU' if cb == 'BF16' else 'BF16'
            other_cyc = r['pipe_cycles'].get(other, 0)
            if other_cyc > 0:
                ratio = r['compute_bottleneck_cyc'] / other_cyc
            print(f'\n  Compute pipes: {cb} = {r["compute_bottleneck_cyc"]} cyc, '
                  f'{other} = {other_cyc} cyc (ratio {ratio:.1f}:1).')
            if ratio < 1.5:
                print(f'  Pipes are reasonably balanced. No substitutions recommended.')
            else:
                print(f'  {cb} is {ratio:.1f}× overloaded vs {other}, but no '
                      f'substitutable ops found on the bottleneck pipe.')

    print()


def analyze_template_file(path, title=None):
    """Analyze a .s template file's pipe utilization.

    Reads the file, extracts instruction mnemonics, runs analyze_pipes.
    """
    if title is None:
        title = os.path.basename(path)

    with open(path) as f:
        lines = f.readlines()

    mnemonics = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#') or stripped.startswith('.'):
            continue
        mnemonics.append(stripped)

    return analyze_pipes(mnemonics, title=title)


# CLI entry point for standalone analysis
if __name__ == '__main__':
    import sys
    if len(sys.argv) < 2:
        print('Usage: python3 sm100a_encoding.py <template.s> [title]')
        print('       python3 sm100a_encoding.py --compare <a.s> <b.s>')
        sys.exit(1)

    if sys.argv[1] == '--compare' and len(sys.argv) >= 4:
        r1 = analyze_template_file(sys.argv[2])
        r2 = analyze_template_file(sys.argv[3])
        # Print side-by-side bottleneck comparison
        print(f'\n{"=" * 70}')
        print(f'  COMPARISON (compute pipes only)')
        print(f'{"=" * 70}')
        n1 = os.path.basename(sys.argv[2])
        n2 = os.path.basename(sys.argv[3])
        cb1 = r1['compute_bottleneck']
        cb2 = r2['compute_bottleneck']
        cc1 = r1['compute_bottleneck_cyc']
        cc2 = r2['compute_bottleneck_cyc']
        print(f'  {n1:<30} compute bottleneck: {cb1} = {cc1} cyc')
        print(f'  {n2:<30} compute bottleneck: {cb2} = {cc2} cyc')

        # Per-pipe comparison
        for p in ('BF16', 'ALU'):
            c1p = r1['pipe_cycles'].get(p, 0)
            c2p = r2['pipe_cycles'].get(p, 0)
            if c1p or c2p:
                print(f'    {p:<8} {c1p:>6} cyc vs {c2p:>6} cyc')

        # Note: templates cover different col ranges, so normalize per-col
        t1 = r1['total_insns']
        t2 = r2['total_insns']
        if t1 != t2:
            print(f'\n  ℹ  Templates cover different scope ({t1} vs {t2} insns).')
            print(f'     Pipe ratios matter more than absolute cycle counts.')

        # Compute pipe ratio (BF16:ALU imbalance) — the actionable metric
        for name, r in [(n1, r1), (n2, r2)]:
            bf16 = r['pipe_cycles'].get('BF16', 0)
            alu = r['pipe_cycles'].get('ALU', 0)
            if bf16 > 0 and alu > 0:
                ratio = bf16 / alu
                print(f'  {name:<30} BF16:ALU ratio = {ratio:.1f}:1')
            elif bf16 > 0:
                print(f'  {name:<30} BF16:ALU ratio = ∞ (no ALU compute)')
        print()
    else:
        title = sys.argv[2] if len(sys.argv) > 2 else None
        analyze_template_file(sys.argv[1], title=title)
